mapper.update:
update user_profile set
  assessment_id = #{assessmentId}, nickname = #{nickname}, age = #{age}, gender = #{gender},
  grade = #{grade}, city = #{city}, stage = #{stage}, mbti = #{mbti}, holland_code = #{hollandCode},
  completeness = #{completeness}, summary = #{summary}, summary_status = #{summaryStatus},
  profile_json = #{profileJson}, updated_at = #{updatedAt}
where id = #{id}
